const source = $json;
const record = Array.isArray(source.records) ? source.records[0] : source;

if (!record || !record.id) {
  return [];
}

const fields = record.fields || {};
const dailyRequests = Number(fields.daily_requests ?? 0);
const status = String(fields.status || 'free');

return [
  {
    json: {
      record_id: record.id,
      telegram_id: String($node['Telegram Trigger'].json.message.from.id),
      chat_id: String($node['Telegram Trigger'].json.message.chat.id),
      voice_file_id: $node['Telegram Trigger'].json.message.voice.file_id,
      daily_requests: dailyRequests,
      status,
      request_log: String(fields.request_log || ''),
      limit_exceeded: status === 'free' && dailyRequests >= 10
    }
  }
];

const text = String($json.text || $json.transcription || '').trim();

return [
  {
    json: {
      text,
      is_valid: text.length >= 5
    }
  }
];

const message = $json.output?.find?.((item) => item.type === 'message') || $json.output?.[0];
const raw = String(
  message?.content?.find?.((part) => part.type === 'output_text')?.text ||
  message?.content?.[0]?.text ||
  $json.text ||
  ''
).trim();

function escapeMarkdownV2(value) {
  return value.replace(/([_*\[\]()~`>#+\-=|{}.!])/g, '\\$1');
}

const boldParts = [];
let prepared = raw.replace(/\*\*([\s\S]*?)\*\*/g, (_, inner) => {
  const token = '@@BOLDTOKEN' + boldParts.length + '@@';
  boldParts.push({ token, value: '*' + escapeMarkdownV2(inner) + '*' });
  return token;
});

prepared = escapeMarkdownV2(prepared);

for (const part of boldParts) {
  prepared = prepared.split(part.token).join(part.value);
}

return [
  {
    json: {
      raw_text: raw,
      telegram_text: prepared
    }
  }
];

parameters.jsonBody:
={{ { fields: {
  daily_requests: $node['Code - Normalize Airtable User'].json.daily_requests + 1,
  updated_at: $now.toISO(),
  last_request_at: $now.toISO(),
  last_raw_text: $node['Code - Validate Transcription'].json.text,
  last_result: $node['Code - Prepare Telegram MarkdownV2'].json.raw_text,
  request_log: (() => {
    const oldLog = String($node['Code - Normalize Airtable User'].json.request_log || '');
    const raw = String($node['Code - Validate Transcription'].json.text || '').slice(0, 4000);
    const result = String($node['Code - Prepare Telegram MarkdownV2'].json.raw_text || '').slice(0, 6000);
    const entry = '[' + $now.toISO() + ']\nRAW: ' + raw + '\nRESULT: ' + result + '\n---\n';
    return (entry + oldLog).slice(0, 95000);
  })()
}, typecast: true } }}

